<?php
declare(strict_types=1);namespace App\Application\Payments;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Application\Payments\Adapters\PaymentAdapterRegistry;use App\Models\{PaymentAttempt,PaymentIntentRecord,PaymentProviderConnection};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;use Throwable;
final class PaymentInitiationService{public function __construct(private PaymentAdapterRegistry$adapters,private AuditWriter$audit,private OutboxWriter$outbox,private ExecutionModes\PaymentCollectionModeService$collectionModes){}/** @param array{retry_of_attempt_id?:string,retry_idempotency_key?:string,requested_by?:string} $attemptMeta set by Retries\PaymentRetryService (REQ-PAY-008) */public function initiate(PaymentIntentRecord$i,array$attemptMeta=[]):PaymentIntentRecord{if(!in_array($i->status,['CREATED','PENDING_CUSTOMER','FAILED'],true))throw ValidationException::withMessages(['status'=>__('wave4.payment_not_initiable')]);/* Only seeded demo personas get the fake adapter in demo mode (audit A2); everyone else needs a live provider connection. */$demo=\App\Application\Demo\DemoPersonas::ownsPayment($i);if(!$demo&&$i->provider==='fake'&&!app()->environment('local','testing'))throw ValidationException::withMessages(['provider'=>__('wave4.provider_not_configured')]);if(!$demo&&$i->provider!=='fake'&&!PaymentProviderConnection::where('provider',$i->provider)->where('status','ACTIVE')->where(fn($q)=>$q->where('tenant_id',$i->tenant_id)->orWhereNull('tenant_id'))->exists())throw ValidationException::withMessages(['provider'=>__('wave4.provider_not_active')]);/* REQ-PAY-014 / REQ-AOM-002: capability-pinned PaymentExecution — only an on-platform collection mode (MOBILE_MONEY) may prompt the payer. */$i=$this->collectionModes->gate($i);return DB::transaction(function()use($i,$demo,$attemptMeta){$locked=PaymentIntentRecord::whereKey($i->id)->lockForUpdate()->firstOrFail();$number=($locked->attempts()->max('attempt_number')??0)+1;$requestId=(string)Str::uuid();$attempt=PaymentAttempt::create(['payment_intent_id'=>$locked->id,'attempt_number'=>$number,'provider_request_id'=>$requestId,'status'=>'STARTED','collection_mode'=>$locked->collection_mode,'request_snapshot'=>['amount_minor'=>$locked->amount_minor,'currency'=>$locked->currency,'payer_hash'=>hash('sha256',$locked->payer_phone_e164)],'started_at'=>now(),...array_intersect_key($attemptMeta,array_flip(['retry_of_attempt_id','retry_idempotency_key','requested_by']))]);try{$result=$this->adapters->for($locked->provider,$demo)->requestCustomerAuthorization($locked,$requestId);$attempt->update(['status'=>'ACCEPTED','response_snapshot'=>$result->safeResponse,'completed_at'=>now()]);$locked->update(['provider_reference'=>$result->providerReference,'status'=>$result->status,'customer_prompted_at'=>now()]);$this->audit->record('payment.authorization.requested','payment_intent',$locked->id,['provider'=>$locked->provider,'attempt'=>$number]);$this->outbox->record('payment.authorization.requested','payment_intent',$locked->id,['payment_intent_id'=>$locked->id]);}catch(Throwable$e){$attempt->update(['status'=>'FAILED','failure_code'=>'PROVIDER_REQUEST_FAILED','completed_at'=>now()]);$locked->update(['status'=>'FAILED']);$this->audit->record('payment.authorization.failed','payment_intent',$locked->id,['provider'=>$locked->provider]);throw$e;}return$locked->refresh();});}}
